const defaults = {
    capFeedUrl: "https://alerts.metservice.com/cap/rss",
    portalId: "",
    home: { lat: null, lon: null, name: "Home" },
    useVictronGps: true,
    homeAreaKeywords: [],
    matchAllWithoutGeometry: false,
    leadMinutes: 30,
    clearHoldMinutes: 60,
    normalMinSoc: 20,
    stormMinSoc: 80,
    acceptedSeverities: ["Moderate", "Severe", "Extreme"],
    stormKeywords: [
        "storm",
        "thunderstorm",
        "severe weather",
        "heavy rain",
        "flood",
        "wind",
        "gale",
        "squall",
        "cyclone",
        "tornado",
        "hail",
        "snow",
        "ice"
    ]
};

const runtime = flow.get("stormConfigRuntime") || {};
const cfg = {
    ...defaults,
    ...runtime,
    home: {
        ...defaults.home,
        ...(runtime.home || {})
    }
};

cfg.normalMinSoc = Math.round(Math.max(0, Math.min(100, Number(cfg.normalMinSoc) || 20)) / 5) * 5;
cfg.stormMinSoc = Math.round(Math.max(0, Math.min(100, Number(cfg.stormMinSoc) || 80)) / 5) * 5;

flow.set("stormConfig", cfg);
msg.stormConfig = cfg;
return msg;

const cfg = msg.stormConfig || flow.get("stormConfig") || {};
const capUrl = cfg.capFeedUrl || "https://alerts.metservice.com/cap/rss";
msg.method = "GET";
msg.url = `${capUrl}${capUrl.includes("?") ? "&" : "?"}_ts=${Date.now()}`;
msg.headers = { "User-Agent": "victron-storm-watch/2.0" };
return msg;

function asArray(v) {
    if (v === undefined || v === null) return [];
    return Array.isArray(v) ? v : [v];
}

function text(v) {
    if (Array.isArray(v)) {
        for (const i of v) {
            const t = text(i);
            if (t) return t;
        }
        return "";
    }
    if (typeof v === "object" && v !== null) {
        if (v._ !== undefined) return String(v._).trim();
        return "";
    }
    return String(v).trim();
}

const p = msg.payload || {};
let items = [];

if (p.rss && p.rss.channel) {
    items = asArray((asArray(p.rss.channel)[0] || {}).item);
} else if (p.feed && p.feed.entry) {
    items = asArray(p.feed.entry);
}

msg.alerts = items.map((item) => ({
    title: text(item.title),
    event: text(item["cap:event"]) || text(item.title),
    description: text(item.description) || text(item.summary),
    severity: text(item["cap:severity"]),
    area: text(item["cap:areaDesc"]) || text(item["cap:area"]),
    onset: text(item["cap:onset"]),
    effective: text(item["cap:effective"]),
    expires: text(item["cap:expires"]),
    pubDate: text(item.pubDate),
    polygons: asArray(item["cap:polygon"]).map(text).filter(Boolean),
    circles: asArray(item["cap:circle"]).map(text).filter(Boolean)
}));

return msg;

function asArray(v) {
    if (v === undefined || v === null) return [];
    return Array.isArray(v) ? v : [v];
}
function num(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}
function parseDateMs(v) {
    if (!v) return null;
    const ms = Date.parse(String(v).trim());
    return Number.isFinite(ms) ? ms : null;
}
function parsePolygon(polyText) {
    const points = [];
    for (const pair of String(polyText || "").trim().split(/\s+/)) {
        if (!pair) continue;
        const parts = pair.split(",");
        if (parts.length !== 2) continue;
        const lat = num(parts[0]);
        const lon = num(parts[1]);
        if (lat === null || lon === null) continue;
        points.push([lat, lon]);
    }
    return points;
}
function pointInPolygon(lat, lon, points) {
    let inside = false;
    const x = lon;
    const y = lat;
    for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
        const yi = points[i][0];
        const xi = points[i][1];
        const yj = points[j][0];
        const xj = points[j][1];
        const intersects = ((yi > y) !== (yj > y)) &&
            (x < ((xj - xi) * (y - yi)) / ((yj - yi) || 1e-12) + xi);
        if (intersects) inside = !inside;
    }
    return inside;
}
function parseCircle(circleText) {
    const parts = String(circleText || "").trim().split(/\s+/);
    if (parts.length < 2) return null;
    const center = parts[0].split(",");
    if (center.length !== 2) return null;
    const lat = num(center[0]);
    const lon = num(center[1]);
    const radiusKm = num(parts[1]);
    if (lat === null || lon === null || radiusKm === null || radiusKm < 0) return null;
    return { lat, lon, radiusKm };
}
function haversineKm(lat1, lon1, lat2, lon2) {
    const toRad = (d) => d * Math.PI / 180;
    const R = 6371;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2 +
        Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(a));
}

const cfg = msg.stormConfig || flow.get("stormConfig") || {};
const now = Date.now();
const leadMs = Math.max(0, (num(cfg.leadMinutes) || 0) * 60000);
const holdMs = Math.max(0, (num(cfg.clearHoldMinutes) || 0) * 60000);

const gpsLat = num(flow.get("gpsLatitude"));
const gpsLon = num(flow.get("gpsLongitude"));
const cfgLat = num((cfg.home || {}).lat);
const cfgLon = num((cfg.home || {}).lon);

let homeLat = cfgLat;
let homeLon = cfgLon;
let homeSource = "config";
if (cfg.useVictronGps && gpsLat !== null && gpsLon !== null) {
    homeLat = gpsLat;
    homeLon = gpsLon;
    homeSource = "victron-gps";
}
const hasHome = homeLat !== null && homeLon !== null;

const acceptedSeverity = new Set(asArray(cfg.acceptedSeverities).map((s) => String(s).toLowerCase()));
const stormKeywords = asArray(cfg.stormKeywords).map((s) => String(s).toLowerCase()).filter(Boolean);
const areaKeywords = asArray(cfg.homeAreaKeywords).map((s) => String(s).toLowerCase()).filter(Boolean);

const matched = [];
for (const a of asArray(msg.alerts)) {
    const searchable = `${a.event || ""} ${a.title || ""} ${a.description || ""}`.toLowerCase();
    if (stormKeywords.length && !stormKeywords.some((k) => searchable.includes(k))) continue;

    const severity = String(a.severity || "").toLowerCase();
    if (acceptedSeverity.size && !acceptedSeverity.has(severity)) continue;

    const onsetMs = parseDateMs(a.onset) || parseDateMs(a.effective);
    const effectiveMs = parseDateMs(a.effective);
    const expiresMs = parseDateMs(a.expires) || parseDateMs(a.pubDate);
    const startsMs = onsetMs || effectiveMs || now;

    if (startsMs - leadMs > now) continue;
    if (expiresMs !== null && expiresMs < now) continue;

    let inZone = false;
    let zoneType = "none";
    const parsedPolygons = [];
    const parsedCircles = [];

    if (hasHome) {
        for (const polyText of asArray(a.polygons)) {
            const pts = parsePolygon(polyText);
            if (pts.length >= 3) {
                parsedPolygons.push(pts);
                if (!inZone && pointInPolygon(homeLat, homeLon, pts)) {
                    inZone = true;
                    zoneType = "polygon";
                }
            }
        }
        for (const circleText of asArray(a.circles)) {
            const c = parseCircle(circleText);
            if (!c) continue;
            parsedCircles.push(c);
            if (!inZone && haversineKm(homeLat, homeLon, c.lat, c.lon) <= c.radiusKm) {
                inZone = true;
                zoneType = "circle";
            }
        }
    }

    if (!inZone && areaKeywords.length) {
        const areaNorm = String(a.area || "").toLowerCase();
        if (areaKeywords.some((k) => areaNorm.includes(k))) {
            inZone = true;
            zoneType = "area-keyword";
        }
    }

    if (!inZone && cfg.matchAllWithoutGeometry && (!a.polygons || !a.polygons.length) && (!a.circles || !a.circles.length)) {
        inZone = true;
        zoneType = "no-geometry-fallback";
    }

    if (!inZone) continue;

    matched.push({
        title: a.title,
        event: a.event,
        severity: a.severity || "Unknown",
        area: a.area,
        zoneType,
        startsAt: startsMs ? new Date(startsMs).toISOString() : null,
        expiresAt: expiresMs ? new Date(expiresMs).toISOString() : null,
        expiresTs: expiresMs,
        polygons: parsedPolygons,
        circles: parsedCircles
    });
}

let holdUntil = num(flow.get("stormHoldUntil")) || 0;
let shouldProtect = matched.length > 0;
let reason = shouldProtect ? "active-alert" : "clear";

if (shouldProtect) {
    let furthestExpiry = 0;
    for (const m of matched) {
        if (m.expiresTs && m.expiresTs > furthestExpiry) furthestExpiry = m.expiresTs;
    }
    holdUntil = (furthestExpiry || now) + holdMs;
    flow.set("stormHoldUntil", holdUntil);
} else if (holdUntil > now) {
    shouldProtect = true;
    reason = "hold-timer";
} else {
    flow.set("stormHoldUntil", 0);
}

const manualMode = String(flow.get("stormManualMode") || "auto");
if (manualMode === "force_on") {
    shouldProtect = true;
    reason = "manual-force-on";
} else if (manualMode === "force_off") {
    shouldProtect = false;
    reason = "manual-force-off";
}

const discoveredPortalId = flow.get("portalId") || "";
const portalId = cfg.portalId || discoveredPortalId;

msg.stormWatch = {
    timestamp: new Date(now).toISOString(),
    shouldProtect,
    reason,
    matchedCount: matched.length,
    matchedAlerts: matched.slice(0, 10),
    holdUntil: holdUntil ? new Date(holdUntil).toISOString() : null,
    portalId: portalId || null,
    home: {
        lat: homeLat,
        lon: homeLon,
        source: hasHome ? homeSource : "missing"
    },
    control: {
        normalMinSoc: cfg.normalMinSoc,
        stormMinSoc: cfg.stormMinSoc
    },
    manualMode
};

if (!hasHome) {
    msg.stormWatch.warning = "Home location is missing. Configure home lat/lon or provide Victron GPS.";
}

return msg;

const info = msg.stormWatch || {};
const prev = !!flow.get("stormProtectActive");
const next = !!info.shouldProtect;
const portalId = info.portalId || flow.get("portalId") || "";

function clampSocStep5(v, fallback) {
    const n = Number(v);
    const base = Number.isFinite(n) ? n : fallback;
    const clipped = Math.max(0, Math.min(100, base));
    return Math.round(clipped / 5) * 5;
}

const normalMinSoc = clampSocStep5(info.control && info.control.normalMinSoc, 20);
const stormMinSoc = clampSocStep5(info.control && info.control.stormMinSoc, 80);

function settingMsg(path, value) {
    return {
        topic: `W/${portalId}/settings/0/${path}`,
        payload: JSON.stringify({ value })
    };
}

if (!portalId) {
    return [null, { payload: { level: "warn", text: "Portal ID unknown; waiting for N/<portalId>/... topics", stormWatch: info } }];
}

if (next && !prev) {
    flow.set("stormProtectActive", true);
    return [[
        settingMsg("Settings/CGwacs/BatteryLife/MinimumSocLimit", stormMinSoc),
        settingMsg("Settings/CGwacs/BatteryLife/ForceCharge", 1)
    ], { payload: { level: "info", text: `Storm protection ENABLED (${stormMinSoc}%)`, stormWatch: info } }];
}

if (!next && prev) {
    flow.set("stormProtectActive", false);
    return [[
        settingMsg("Settings/CGwacs/BatteryLife/ForceCharge", 0),
        settingMsg("Settings/CGwacs/BatteryLife/MinimumSocLimit", normalMinSoc)
    ], { payload: { level: "info", text: `Storm protection DISABLED (${normalMinSoc}%)`, stormWatch: info } }];
}

return [null, { payload: { level: "debug", text: "No ESS setting change", stormWatch: info } }];

const sw = msg.stormWatch || {};
const cfg = flow.get("stormConfig") || {};
const manualMode = sw.manualMode || flow.get("stormManualMode") || "auto";

const home = sw.home || {};
const homeStr = (home.lat !== null && home.lat !== undefined && home.lon !== null && home.lon !== undefined)
    ? `${Number(home.lat).toFixed(5)}, ${Number(home.lon).toFixed(5)} (${home.source || "unknown"})`
    : "Home location missing";

const settingsPreset = {
    capFeedUrl: cfg.capFeedUrl || "",
    homeLat: (cfg.home && cfg.home.lat !== null && cfg.home.lat !== undefined) ? String(cfg.home.lat) : "",
    homeLon: (cfg.home && cfg.home.lon !== null && cfg.home.lon !== undefined) ? String(cfg.home.lon) : "",
    normalMinSoc: cfg.normalMinSoc || 20,
    stormMinSoc: cfg.stormMinSoc || 80,
    leadMinutes: cfg.leadMinutes || 30,
    clearHoldMinutes: cfg.clearHoldMinutes || 60,
    acceptedSeverities: (cfg.acceptedSeverities || []).join(", "),
    stormKeywords: (cfg.stormKeywords || []).join(", "),
    homeAreaKeywords: (cfg.homeAreaKeywords || []).join(", "),
    useVictronGps: String(!!cfg.useVictronGps),
    matchAllWithoutGeometry: String(!!cfg.matchAllWithoutGeometry)
};

const alerts = sw.matchedAlerts || [];
const top = alerts.length ? alerts[0] : null;
const insight = {
    shouldProtect: !!sw.shouldProtect,
    reason: sw.reason || "-",
    matchedCount: Number(sw.matchedCount || 0),
    holdUntil: sw.holdUntil || null,
    manualMode,
    warning: sw.warning || null,
    topAlert: top ? {
        event: top.event || top.title || "-",
        severity: top.severity || "Unknown",
        zoneType: top.zoneType || "-",
        area: top.area || "-",
        startsAt: top.startsAt || null,
        expiresAt: top.expiresAt || null
    } : null
};

const chartPayload = {
    topic: "protect",
    payload: sw.shouldProtect ? 1 : 0,
    timestamp: Date.now()
};

return [
    { payload: sw.shouldProtect ? "PROTECT ACTIVE" : "NORMAL" },
    { payload: sw.reason || "-" },
    { payload: String(sw.matchedCount || 0) },
    { payload: homeStr },
    { payload: sw.holdUntil || "-" },
    { payload: sw.portalId || flow.get("portalId") || "(discovering)" },
    { payload: { home: sw.home || {}, alerts } },
    { payload: { alerts } },
    { payload: settingsPreset },
    { payload: manualMode },
    chartPayload,
    { payload: insight }
];

const t = String(msg.topic || "");
const m = t.match(/^N\/([^/]+)\//);
if (m) flow.set("portalId", m[1]);

let value = msg.payload;
if (value && typeof value === "object" && value.value !== undefined) value = value.value;
const soc = Number(value);
if (Number.isFinite(soc)) flow.set("batterySoc", soc);
return null;

const t = String(msg.topic || "");
const m = t.match(/^N\/([^/]+)\//);
if (m) flow.set("portalId", m[1]);

let value = msg.payload;
if (value && typeof value === "object" && value.value !== undefined) value = value.value;

function setIfFinite(key, v) {
    const n = Number(v);
    if (Number.isFinite(n)) {
        flow.set(key, n);
        return true;
    }
    return false;
}

const tl = t.toLowerCase();
if (tl.endsWith("/latitude") || tl.endsWith("/lat")) setIfFinite("gpsLatitude", value);
if (tl.endsWith("/longitude") || tl.endsWith("/lon") || tl.endsWith("/lng")) setIfFinite("gpsLongitude", value);

if (value && typeof value === "object") {
    setIfFinite("gpsLatitude", value.latitude);
    setIfFinite("gpsLatitude", value.lat);
    setIfFinite("gpsLongitude", value.longitude);
    setIfFinite("gpsLongitude", value.lon);
    setIfFinite("gpsLongitude", value.lng);
}

return null;

const input = msg.payload || {};
const runtime = flow.get("stormConfigRuntime") || {};

function numOr(v, fallback) {
    const n = Number(v);
    return Number.isFinite(n) ? n : fallback;
}
function csv(v) {
    return String(v || "").split(",").map((s) => s.trim()).filter(Boolean);
}
function asBool(v, fallback) {
    const s = String(v).trim().toLowerCase();
    if (s === "true" || s === "1" || s === "yes" || s === "on") return true;
    if (s === "false" || s === "0" || s === "no" || s === "off") return false;
    return fallback;
}

runtime.capFeedUrl = String(input.capFeedUrl || runtime.capFeedUrl || "https://alerts.metservice.com/cap/rss").trim();
runtime.home = runtime.home || {};

const homeLat = String(input.homeLat || "").trim();
const homeLon = String(input.homeLon || "").trim();
runtime.home.lat = homeLat === "" ? null : numOr(homeLat, null);
runtime.home.lon = homeLon === "" ? null : numOr(homeLon, null);

runtime.normalMinSoc = Math.round(Math.max(0, Math.min(100, numOr(input.normalMinSoc, runtime.normalMinSoc || 20))) / 5) * 5;
runtime.stormMinSoc = Math.round(Math.max(0, Math.min(100, numOr(input.stormMinSoc, runtime.stormMinSoc || 80))) / 5) * 5;
runtime.leadMinutes = Math.max(0, Math.floor(numOr(input.leadMinutes, runtime.leadMinutes || 30)));
runtime.clearHoldMinutes = Math.max(0, Math.floor(numOr(input.clearHoldMinutes, runtime.clearHoldMinutes || 60)));
runtime.acceptedSeverities = csv(input.acceptedSeverities);
runtime.stormKeywords = csv(input.stormKeywords);
runtime.homeAreaKeywords = csv(input.homeAreaKeywords);
runtime.useVictronGps = asBool(input.useVictronGps, true);
runtime.matchAllWithoutGeometry = asBool(input.matchAllWithoutGeometry, false);

flow.set("stormConfigRuntime", runtime);

return [
    { topic: "poll", payload: Date.now() },
    { payload: `Storm settings saved. MinSoC normal/storm: ${runtime.normalMinSoc}/${runtime.stormMinSoc}` }
];

const mode = String(msg.payload || "auto");
flow.set("stormManualMode", mode);
return [
    { topic: "poll", payload: Date.now() },
    { payload: `Manual override set to: ${mode}` }
];
